    memset(p, 0, bytes); // 호출자가 유효한 버퍼 용량을 전달해야 함
}

rules.badExample:
if (strcmp("ON", "OFF") == 0) {
    activate(); // 이 조건은 거짓
}

rules.goodExample:
/* 실제 입력과 비교하려는 의도일 때 */
if (strcmp(input, "ON") == 0) {
    activate();
}

rules.badExample:
struct State { int ready; int count; };
